import{_ as e,a,o as i,a4 as r}from"./chunks/framework.-FZumj2l.js";const b=JSON.parse('{"title":"Catalog Attribute — Delete (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-attribute-delete","title":"Delete Attribute","description":"Deletes a user-defined attribute and returns the deleted snapshot. Refused for system attributes and attributes still attached to families.","query":"mutation DeleteAttribute($input: deleteAdminAttributeInput!) {\\n  deleteAdminAttribute(input: $input) {\\n    adminAttribute {\\n      id\\n      _id\\n      code\\n      type\\n      adminName\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/catalog/attributes/50\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"deleteAdminAttribute\\": {\\n      \\"adminAttribute\\": {\\n        \\"id\\": \\"/api/admin/catalog/attributes/50\\",\\n        \\"_id\\": 50,\\n        \\"code\\": \\"color\\",\\n        \\"type\\": \\"select\\",\\n        \\"adminName\\": \\"Color\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/attributes/attributes-delete.md","filePath":"api/graphql-api/admin/catalog/attributes/attributes-delete.md","lastUpdated":1784902076000}'),d={name:"api/graphql-api/admin/catalog/attributes/attributes-delete.md"};function n(o,t,s,l,u,p){return i(),a("div",null,t[0]||(t[0]=[r('<h1 id="catalog-attribute-—-delete-graphql" tabindex="-1">Catalog Attribute — Delete (GraphQL) <a class="header-anchor" href="#catalog-attribute-—-delete-graphql" aria-label="Permalink to &quot;Catalog Attribute — Delete (GraphQL)&quot;">​</a></h1><p>Deletes a user-defined attribute. <code>id</code> is the attribute IRI (<code>/api/admin/catalog/attributes/{id}</code>). The mutation returns a snapshot of the deleted attribute.</p><p>A system attribute (<code>isUserDefined = 0</code>) cannot be deleted (<code>403</code>), and an attribute still attached to one or more attribute families is refused until it is removed from those families (<code>409</code>).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>See the <a href="/api/graphql-api/admin/catalog/attributes/">Attributes overview</a> for how attributes, options, and families fit together.</p></div><p>Each failure returns an <code>errors[]</code> entry:</p><table tabindex="0"><thead><tr><th>Condition</th><th>Message</th></tr></thead><tbody><tr><td>System attribute (<code>isUserDefined = 0</code>)</td><td><code>System attributes cannot be deleted.</code></td></tr><tr><td>Attribute is referenced by one or more attribute families</td><td><code>Attribute is part of one or more attribute families. Remove it from those families first.</code></td></tr><tr><td>Unknown id</td><td><code>Attribute not found.</code></td></tr></tbody></table><p>For bulk deletion, use <a href="/api/graphql-api/admin/catalog/attributes/attributes-mass-delete.html"><code>createAdminAttributeMassDelete</code></a>.</p><p>All admin operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',8)]))}const m=e(d,[["render",n]]);export{b as __pageData,m as default};
